import{_ as u,a0 as a,w as s,s as p,ao as r,I as i,x as n,a1 as t,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"戴文的Linux內核專題：05 配置內核 (1) | LCTT x X-CMD","titleTemplate":false,"description":"戴文的Linux內核專題：05 配置內核 (1) | LCTT (The Linux Kernel) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"戴文的Linux內核專題：05 配置內核 (1) | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"戴文的Linux內核專題：05 配置內核 (1) | LCTT (The Linux Kernel) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The Linux Kernel/05 The Linux Kernel--Configuring the Kernel Part 1","title":"戴文的Linux內核專題：05 配置內核 (1)","tag":"The Linux Kernel","desc":""},"relativePath":"The Linux Kernel/05 The Linux Kernel--Configuring the Kernel Part 1.md","filePath":"[post].md"}'),g={name:"The Linux Kernel/05 The Linux Kernel--Configuring the Kernel Part 1.md"};function m(f,e,d,L,x,T){const l=a("Link");return s(),p("div",null,[e[17]||(e[17]=r('<h1 id="戴文的linux內核專題-05-配置內核-1" tabindex="-1">戴文的Linux內核專題：05 配置內核 (1) <a class="header-anchor" href="#戴文的linux內核專題-05-配置內核-1" aria-label="Permalink to “戴文的Linux內核專題：05 配置內核 (1)”">​</a></h1><p><img src="http://www.linux.org/attachments/slide-jpg.299/" alt=""></p><p>現在我們已經瞭解了內核，現在我們可以進入主要工作：配置並編譯內核代碼。配置內核代碼並不會花費太長時間。配置工具會詢問許多問題並且允許開發者配置內核的每個方面。如果你有不確定的問題或者特性，你最好使用配置工具提供的默認值。本系列教程會使讀者逐步瞭解配置內核的整個過程。</p><p>配置代碼前需要在源文件的文件夾內打開一個終端。當終端打開後，基於你喜好的配置界面，這裏有幾種不同的配置方法：</p><ul><li>make config - 純文本界面 (最常用的選擇)。</li><li>make menuconfig - 基於文本彩色菜單和單選列表。這個選項可以加快開發者開發速度。需要安裝ncurses(ncurses-devel)。</li><li>make nconfig - 基於文本的彩色菜單。需要安裝curses (libcdk5-dev)。</li><li>make xconfig - QT/X-windows 界面。需要安裝QT。</li><li>make gconfig - Gtk/X-windows 界面。需要安裝GTK。</li><li>make oldconfig - 純文本界面，但是其默認的問題是基於已有的本地配置文件。</li><li>make silentoldconfig - 和oldconfig相似，但是不會顯示配置文件中已有的問題的回答。</li><li>make olddefconfig -和silentoldconfig相似，但有些問題已經以它們的默認值選擇。</li><li>make defconfig - 這個選項將會創建一份以當前系統架構為基礎的默認設置文件。</li><li>make ${PLATFORM}_defconfig - 創建一份使用arch/$ARCH/configs/${PLATFORM}_defconfig中的值的配置文件。</li><li>make allyesconfig - 這個選項將會創建一份儘可能多的問題回答都為‘yes’的配置文件。</li><li>make allmodconfig - 這個選項將會創建一份將盡可能多的內核部分配置為模組的配置文件。</li></ul><blockquote><p>注意：內核代碼可以放進內核自身，也可以成為一個模組。例如，用户可以將藍牙驅動作為一個模組加入(獨立於內核)，或者直接放到內核裏，或者完全不加藍牙驅動。當代碼放到內核本身時，內核將會請求更多的內存並且啓動會花費更長的時間。然而，內核會執行的更好。如果代碼作為模組加入，代碼將會一直存在於硬盤上直到被需要時加載。接着模組被加載到內存中。這可以減少內核的內存使用並減少啓動的時間。然而，因為內核和模組在內存上相互獨立所以會影響內核的性能。另一種選擇是不添加一些代碼。舉例來説，內核開發人員假如知道系統永遠都不會使用藍牙設備，因此這個驅動就可以不加到內核中。這提升了內核的性能。然而，如果用户之後需要藍牙設備，那麼他麼需要安裝藍牙模組或者升級內核才行。</p></blockquote>',6)),i("ul",null,[e[3]||(e[3]=i("li",null,"make allnoconfig - 這個選項只會生成內核所必要代碼的配置文件。它對儘可能多的問題都回答no。這有時會導致內核無法工作在為編譯該內核的硬件上。",-1)),e[4]||(e[4]=i("li",null,"make randconfig - 這個選項會對內核選項隨機選擇（譯註：這是做什麼用途的？！）。",-1)),e[5]||(e[5]=i("li",null,"make localmodconfig - 這個選項會根據當前已加載模組列表和系統配置來生成配置文件。",-1)),i("li",null,[e[1]||(e[1]=n("make localyesconfig - 將所有可裝載模組（LKM）都編譯進內核(譯者注：這裏與原文 ‘This will set all module options to yes - most (or all) of the kernel will not be in modules’的意思不同，作者也作出瞭解釋：",-1)),t(l,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-1.4274/#post-13307"},{default:o(()=>[...e[0]||(e[0]=[n("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-1.4274/#post-13307",-1)])]),_:1}),e[2]||(e[2]=n(")。",-1))])]),e[18]||(e[18]=r('<p>貼士：最好使用“make menuconfig”，因為用户可以保存進度。“make config”不會提供這樣的便利，因為配置過程會耗費大量時間。</p><h3 id="配置" tabindex="-1">配置: <a class="header-anchor" href="#配置" aria-label="Permalink to “配置:”">​</a></h3><p>大多數開發者選擇使用“make menucongfig”或者其他圖形菜單之一。當鍵入上述配置命令後，第一個問題，是受否將內核編譯成64位。選項有“Y”、“n”和“?”。問號用來解釋這個問題，“n”代表這個問題回答否(no),&quot;Y&quot;代表這個問題回答是(yes)。在這個教程裏，我選擇是。 這裏我輸入&quot;Y&quot;(這裏是大小寫敏感的)並輸入回車。</p><p>注意：當內核在32位系統上編譯時，編譯工具會詢問內核是否編譯成32位。第一個問題在不同的處理器上不一樣。</p><p>下一行顯示的是&quot;Cross-compiler tool prefix (CROSS_COMPILE) []&quot;（交叉編譯器工具前綴）。如果你不是做交叉編譯就直接按下回車。如果你正在交叉編譯，對ARM系統輸入像&quot;arm-unknown-linux-gnu-&quot;，對64位PC輸入像&quot;x86_64-pc-linux-gnu-&quot;的字樣。對其他處理器而言還有許多其他可能的命令，但是這個表太大了。一旦一名開發者知道他們想要支持的處理器，很容易就可研究出處理器需要的命令。</p><p>注意：交叉編譯是為別的處理器編譯代碼。比如，一台Intel系統正編譯着不在Intel處理器上運行的程序，比如，這個系統可能正在編譯着要在ARM或AMD處理器上運行的代碼。</p><p>注意：每一項選擇會改變接下來顯示什麼問題及何時顯示。我會(在教程裏)包含上我的選擇讓讀者可以在他們自己的系統上跟上配置的進度。</p><p>接下來,用户會看到“Local version - append to kernel release (LOCALVERSION) []”。這使開發人員可以給定一個特殊版本號或命名他們自定義的內核。我將輸入“LinuxDotOrg”，這樣，內核版本會顯示為“3.9.4-LinuxDotOrg”。接下來，配置工具會詢問“Automatically append version information to the version string (LOCALVERSION_AUTO) [N/y/?]”（是否自動添加版本信息到版本號後）。如果本地有一個git版本庫，git的修訂號會被添加到版本號後面。這個例子中我們沒有使用git，所以我回答&quot;no&quot;。不然git修訂號將會追加到版本號中。還記得vmlinuz和幾個類似的文件麼？好了，下一個問題就是問使用哪一種格式壓縮內核。開發人員可以從五個選項中選擇一個。它們是</p><ol><li>Gzip (KERNEL_GZIP)</li><li>Bzip2 (KERNEL_BZIP2)</li><li>LZMA (KERNEL_LZMA)</li><li>XZ (KERNEL_XZ)</li><li>LZO (KERNEL_LZO)</li></ol><p>Gzip是默認值，所以我選擇&quot;1&quot;並按回車。每種壓縮格式和其他壓縮格式相比都有更高或者更低的壓縮比。更好的壓縮比意味着更小的體積，但是與低壓縮比文件相比，它解壓時需要更多的時間。</p><p>現在這行顯示“Default hostname (DEFAULT_HOSTNAME) [(none)]”。這裏可以配置主機名。通常地，開發者這行留空(我這裏留空)，以便以後Linux用户可以自己設置他們的主機名。</p><p>接下來開發者可以啓用或者禁用交換分區。Linux使用一個叫做&quot;swap space&quot;的獨立分區來使用虛擬內存。這相當於Windows中的頁面文件。典型地，開發者在這行“Support for paging of anonymous memory (swap) (SWAP) [Y/n/?]”（是否支持匿名內存換頁）回答“Y”。</p><p>接下來的一行（System V IPC (SYSVIPC) [Y/n/?]）詢問內核是否支持IPC。進程間通信使進程間可以通信和同步。最好啓用IPC不然許多程序將無法工作。這個問題回答“Y”會使配置工具接下來問“POSIX Message Queues (POSIX_MQUEUE) [Y/n/?]”（是否使用POSIX消息隊列），這個問題只會在IPC啓用後看見。POSIX消息隊列是一種給每條消息一個優先級的消息隊列（一種進程間通信形式）。默認的選擇是“Y”。按回車選擇默認選擇（以大寫選擇指示默認）。</p><p>下一個問題“open by fhandle syscalls (FHANDLE) [Y/n/?]”（是否使用文件句柄系統調用來打開文件）是問當有需要進行文件系統操作的時候，程序是否允許使用文件句柄而不是文件名進行。默認上，這個選擇是“Y”。</p><p>有時，開發者在做了一些選擇後，某些問題會自動回答。比如，下一個問題“Auditing support (AUDIT) [Y/?]”（是否支持審計）會在沒有提示的情況下自動回答，因為先前的選項需要這個特性。審計支持會記錄所有文件的訪問和修改。下一個關於審計的問題“Enable system-call auditing support (AUDITSYSCALL) [Y/n/?]”（是否啓用系統調用審計支持）。如果啓用，所有的系統調用都會記錄下來。如果開發者想要更好的性能，那麼最好儘可能地禁用審計特性並且不把它加入內核。而另外一些開發者可能為了安全監控而啓用審計。這個問題我選擇“n”。下一個審計方面的問題“Make audit loginuid immutable (AUDIT_LOGINUID_IMMUTABLE) [N/y/?]”（是否要審計進程身份ID不可變）是詢問進程是否可以改變它們的loginuid(LOGIN User ID)，如果啓用，用户空間的進程將無法改變他們的loginuid。為了更好的性能，我們這裏禁用這個特性。（譯註：對於使用systemd這樣的系統，其是通過中央進程來重啓登錄服務的，設置為“y”可以避免一些安全問題；而使用較舊的SysVinit和Upstart的系統，其需要管理員手工重啓登錄服務，應該設置為“N”）</p><p>注意：當通過“make config”配置時，這些通過配置工具回答的問題會顯示出來但是用户無法改變答案。當通過&quot;make menuconfig&quot;配置時，無論用户按任何鍵都無法改變選項。開發者不需要去改變這些選項，因為之前的選擇決定了另外一個問題的選擇。</p><hr>',17)),i("p",null,[e[7]||(e[7]=n("via: ",-1)),t(l,{href:"http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-1.4274/"},{default:o(()=>[...e[6]||(e[6]=[n("http://www.linux.org/threads/the-linux-kernel-configuring-the-kernel-part-1.4274/",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=n("譯者：",-1)),t(l,{href:"https://github.com/geekpi"},{default:o(()=>[...e[8]||(e[8]=[n("geekpi",-1)])]),_:1}),e[11]||(e[11]=n(" 校對：",-1)),t(l,{href:"https://github.com/wxy"},{default:o(()=>[...e[9]||(e[9]=[n("wxy",-1)])]),_:1})]),i("p",null,[e[14]||(e[14]=n("本文由 ",-1)),t(l,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[12]||(e[12]=[n("LCTT",-1)])]),_:1}),e[15]||(e[15]=n(" 原創翻譯，",-1)),t(l,{href:"http://linux.cn/"},{default:o(()=>[...e[13]||(e[13]=[n("Linux中國",-1)])]),_:1}),e[16]||(e[16]=n(" 榮譽推出",-1))])])}const I=u(g,[["render",m]]);export{h as __pageData,I as default};
